// SB10: model output is untrusted. It is tokenised into text, links and images; raw HTML is never
// interpreted (it stays literal text), links need an allowed protocol, images need a listed host.

export const ALLOWED_LINK_PROTOCOLS = ["https:", "mailto:"];
// Policy images come from the library host once it is named; empty means no image ever loads.
export const ALLOWED_IMAGE_HOSTS: readonly string[] = [];

export type Token =
  | { kind: "text"; text: string }
  | { kind: "link"; label: string; href: string }
  | { kind: "image"; alt: string; src: string };

export function safeHref(raw: string): string | null {
  try {
    const url = new URL(raw.trim());
    return ALLOWED_LINK_PROTOCOLS.includes(url.protocol) ? url.href : null;
  } catch {
    return null;
  }
}

export function safeImageSrc(raw: string, hosts: readonly string[] = ALLOWED_IMAGE_HOSTS): string | null {
  try {
    const url = new URL(raw.trim());
    return url.protocol === "https:" && hosts.includes(url.hostname) ? url.href : null;
  } catch {
    return null;
  }
}

const MARKDOWN = /(!?)\[([^\]]*)\]\(([^)\s]*)\)/g;

export function tokenise(source: string, hosts: readonly string[] = ALLOWED_IMAGE_HOSTS): Token[] {
  const tokens: Token[] = [];
  const text = (value: string) => value && tokens.push({ kind: "text", text: value });
  let last = 0;
  for (const match of source.matchAll(MARKDOWN)) {
    text(source.slice(last, match.index));
    last = match.index + match[0].length;
    const [whole, bang, label, target] = match;
    if (bang) {
      const src = safeImageSrc(target, hosts);
      if (src) tokens.push({ kind: "image", alt: label, src });
      else text(label ? `[image: ${label}]` : "[image removed]"); // nothing is fetched
    } else {
      const href = safeHref(target);
      if (href) tokens.push({ kind: "link", label: label || href, href });
      else text(label || whole); // unsafe target: keep the words, drop the link
    }
  }
  text(source.slice(last));
  return tokens;
}
